# ==============================================================================# [Step 2] Unpack Parallax Codebase & Set Up AWS Credentials
import os, io, zipfile, base64

# Set S3 credentials for amazon-ml-challange-2026-parallax
# Load credentials from Kaggle Secrets (Add-ons -> Secrets) or environment
try:
    from kaggle_secrets import UserSecretsClient
    user_secrets = UserSecretsClient()
    os.environ["AWS_ACCESS_KEY_ID"] = user_secrets.get_secret("AWS_ACCESS_KEY_ID")
    os.environ["AWS_SECRET_ACCESS_KEY"] = user_secrets.get_secret("AWS_SECRET_ACCESS_KEY")
except Exception:
    pass

# If not using Kaggle Secrets, paste credentials here:
if not os.environ.get("AWS_ACCESS_KEY_ID"):
    os.environ["AWS_ACCESS_KEY_ID"] = os.getenv("AWS_ACCESS_KEY_ID", "YOUR_AWS_ACCESS_KEY_ID")
    os.environ["AWS_SECRET_ACCESS_KEY"] = os.getenv("AWS_SECRET_ACCESS_KEY", "YOUR_AWS_SECRET_ACCESS_KEY")
os.environ["AWS_DEFAULT_REGION"] = "us-east-1"
os.environ["PARALLAX_S3_BUCKET"] = "amazon-ml-challange-2026-parallax"

# Decode and unpack codebase bundle
b64_data = ""
raw_bytes = base64.b64decode(b64_data)
with zipfile.ZipFile(io.BytesIO(raw_bytes)) as z:
    z.extractall(".")

# Ensure working directory is in python path
import sys
sys.path.insert(0, os.path.abspath("src"))
sys.path.insert(0, os.path.abspath("."))

print("✓ Parallax engine unpacked into /kaggle/working successfully!")

# ==============================================================================# [Step 3] Run End-to-End Production Submission Pipeline
# Runs Stage 0 through Stage 7 (Downloads, Training, Streaming Inference, Validation, S3 Upload)
